package io.github.rebrowser.browser;
import static org.junit.Assert.*;
import io.github.rebrowser.data.*;
import io.github.rebrowser.settings.SettingsRepository;
import java.nio.ByteBuffer;
import java.util.*;
import org.junit.Test;
public class BrowserMetadataModelsTest {
 static String id(String prefix,int n){return prefix+String.format(java.util.Locale.ROOT,"%032x",n);}
 static BookmarkStore.Node link(int n){return new BookmarkStore.Node(id("bm_",n),"收藏","https://example.test/"+n);}
 static HistoryStore.Source source(boolean durable){return new HistoryStore.Source(id("ws_",1),"Source",durable?BrowserModels.Level.SECONDARY:BrowserModels.Level.TEMPORARY,true);}
 static HistoryStore.Page page(){return new HistoryStore.Page(source(false),id("tab_",1),"Title","https://example.test/new");}
 static HistoryStore.Entry visit(int n,long time,boolean retained){return new HistoryStore.Entry(id("hv_",n),id("ws_",1),id("tab_",n),"Source","Title","https://example.test/"+n,time,retained?null:time+HistoryStore.RETENTION_MS,n);}
 @Test public void favoritesFlatRoundTripWithCanonicalBytes(){BookmarkStore.Snapshot s=new BookmarkStore.Snapshot(3,Arrays.asList(link(1),link(2)));byte[] bytes=BookmarkStore.CODEC.encode(s);BookmarkStore.Snapshot decoded=BookmarkStore.CODEC.decode(ByteBuffer.wrap(bytes));assertEquals(3,decoded.metadataRevision());assertEquals(2,decoded.nodes().size());assertArrayEquals(bytes,BookmarkStore.CODEC.encode(decoded));}
 @Test public void unshippedHierarchyRejectedNotSilentlyFlattened(){for(boolean parent:new boolean[]{false,true}){NativeRecordCodec.Writer w=new NativeRecordCodec.Writer("RBBOOK01",200).nonnegative(0).u16(1).text(id("bm_",1),35,false).bool(parent);if(parent)w.text(id("bm_",2),35,false);byte[] bytes=w.bool(true).text("Folder",640,false).text("",8192,true).finish();assertThrows(IllegalArgumentException.class,()->BookmarkStore.CODEC.decode(ByteBuffer.wrap(bytes)));}}
 @Test public void favoritesCountAndDuplicateIdsOrUrlsReject(){List<BookmarkStore.Node> nodes=new ArrayList<>();for(int n=0;n<=BookmarkStore.MAX_NODES;n++)nodes.add(link(n));assertThrows(IllegalArgumentException.class,()->new BookmarkStore.Snapshot(0,nodes));assertThrows(IllegalArgumentException.class,()->new BookmarkStore.Snapshot(0,Arrays.asList(link(1),link(1))));assertThrows(IllegalArgumentException.class,()->new BookmarkStore.Snapshot(0,Arrays.asList(link(1),new BookmarkStore.Node(id("bm_",2),"same","https://example.test/1#fragment"))));}
 @Test public void editAndRemoveBindOriginalUrlNotJustMetadataId(){BookmarkStore.Snapshot s=new BookmarkStore.Snapshot(0,Arrays.asList(link(1),link(2)));assertThrows(IllegalStateException.class,()->s.editExact(id("bm_",1),"https://other.test/","x","https://new.test/"));assertThrows(IllegalStateException.class,()->s.removeExact(id("bm_",1),"https://other.test/"));assertEquals(1,s.removeExact(id("bm_",1),link(1).url()).nodes().size());assertEquals(2,s.nodes().size());assertThrows(IllegalArgumentException.class,()->s.editExact(id("bm_",1),link(1).url(),"duplicate",link(2).url()));}
 @Test public void favoriteCopiesAndEditsDoNotMutatePriorSnapshot(){List<BookmarkStore.Node> input=new ArrayList<>();input.add(link(1));BookmarkStore.Snapshot s=new BookmarkStore.Snapshot(0,input);input.clear();BookmarkStore.Snapshot next=s.add("x","https://example.test/2");assertEquals(1,s.nodes().size());assertEquals(2,next.nodes().size());assertEquals(1,next.metadataRevision());assertThrows(UnsupportedOperationException.class,()->s.nodes().clear());assertSame(next,next.add("duplicate","https://example.test/2/#part"));}
 @Test public void favoritesIdentityIsNotRecentFullUrlIdentity(){assertEquals(BookmarkStore.favoriteKey("https://example.test/path/"),BookmarkStore.favoriteKey("https://example.test/path#part"));assertNotEquals(BookmarkStore.favoriteKey("https://example.test/path?q=1"),BookmarkStore.favoriteKey("https://example.test/path?q=2"));BookmarkStore.Snapshot s=new BookmarkStore.Snapshot(0,Collections.emptyList()).add("","https://example.test/path#original");assertEquals("https://example.test/path#original",s.nodes().get(0).url());assertEquals(s.nodes().get(0).url(),s.nodes().get(0).title());}
 @Test public void unsupportedOrCredentialFavoriteUrlNeverPersists(){for(String url:Arrays.asList("javascript:alert(1)","file:///private/x","https://u:p@example.test/"))assertThrows(IllegalArgumentException.class,()->new BookmarkStore.Node(id("bm_",1),"x",url));}
 @Test public void favoriteAggregateBudgetCannotBeBypassedWithManyBoundedUrls(){List<BookmarkStore.Node> n=new ArrayList<>();String url="https://example.test/"+new String(new char[7000]).replace('\0','x');for(int i=0;i<200;i++)n.add(new BookmarkStore.Node(id("bm_",i),"x",url+i));assertThrows(IllegalArgumentException.class,()->new BookmarkStore.Snapshot(0,n));}
 @Test public void favoriteDecoderRejectsTailsUnknownVersionAndTruncation(){byte[] b=BookmarkStore.CODEC.encode(new BookmarkStore.Snapshot(0,Collections.singletonList(link(1))));assertThrows(IllegalArgumentException.class,()->BookmarkStore.CODEC.decode(ByteBuffer.wrap(Arrays.copyOf(b,b.length+1))));byte[] version=b.clone();version[9]=2;assertThrows(IllegalArgumentException.class,()->BookmarkStore.CODEC.decode(ByteBuffer.wrap(version)));for(int i=0;i<b.length;i++){final byte[] cut=Arrays.copyOf(b,i);assertThrows(IllegalArgumentException.class,()->BookmarkStore.CODEC.decode(ByteBuffer.wrap(cut)));}}
 @Test public void historyStableDescendingOrderAndCanonicalRoundTrip(){HistoryStore.Snapshot s=new HistoryStore.Snapshot(1,false,Arrays.asList(visit(2,5,false),visit(3,10,false),visit(1,10,false)));assertEquals(id("hv_",3),s.entries().get(0).id());assertEquals(id("hv_",1),s.entries().get(1).id());byte[] encoded=HistoryStore.CODEC.encode(s);assertArrayEquals(encoded,HistoryStore.CODEC.encode(HistoryStore.CODEC.decode(ByteBuffer.wrap(encoded))));}
 @Test public void historyPauseIsProcessStateNotPersistentMaintenance(){HistoryStore.RecordingSession process=new HistoryStore.RecordingSession();process.setPaused(true);assertFalse(process.acceptsVisit());HistoryStore.Snapshot s=new HistoryStore.Snapshot(0,true,Collections.singletonList(visit(1,1,false)));assertEquals(2,s.addObservedVisit(page(),2).entries().size());assertThrows(IllegalStateException.class,s::clearTimed);assertFalse(s.withMaintaining(false,3).maintaining());assertFalse(new HistoryStore.RecordingSession().paused());}
 @Test public void historyExactExpiryKeepsLongLivedEntries(){HistoryStore.Snapshot s=new HistoryStore.Snapshot(0,false,Arrays.asList(visit(1,1,true),visit(2,1,false),visit(3,5,false)));HistoryStore.Snapshot next=s.expire(HistoryStore.RETENTION_MS+1);assertEquals(2,next.entries().size());assertEquals(3,s.entries().size());assertThrows(IllegalArgumentException.class,()->s.expire(-1));}
 @Test public void historyNoUnknownRemovalAndNoDuplicateIds(){HistoryStore.Snapshot s=new HistoryStore.Snapshot(0,false,Collections.singletonList(visit(1,1,false)));assertThrows(IllegalArgumentException.class,()->s.remove("unknown"));assertThrows(IllegalArgumentException.class,()->new HistoryStore.Snapshot(0,false,Arrays.asList(visit(1,1,false),visit(1,2,true))));}
 @Test public void historyLiteralPagingAndImmutableSnapshots(){HistoryStore.Snapshot s=new HistoryStore.Snapshot(0,false,Arrays.asList(visit(1,2,false),visit(2,1,false)));assertEquals(id("hv_",2),s.query("Title",1,1).get(0).id());assertEquals(0,s.query(".*",0,1).size());assertThrows(UnsupportedOperationException.class,()->s.entries().clear());assertEquals(3,s.addObservedVisit(page(),3).entries().size());}
 @Test public void historyInvalidInputAndCounterOverflowReject(){assertThrows(IllegalArgumentException.class,()->visit(1,-1,false));HistoryStore.Snapshot s=new HistoryStore.Snapshot(Long.MAX_VALUE,false,Collections.emptyList());assertThrows(IllegalArgumentException.class,()->s.withMaintaining(true,1));assertThrows(IllegalArgumentException.class,()->new HistoryStore.Page(source(false),id("tab_",1),"x","data:text/plain,test"));}
 @Test public void settingsOnlyFourKnownSearchProvidersAndTwoExactSubapps(){for(SearchEngines.Provider p:SearchEngines.Provider.values()){SettingsRepository.Snapshot s=new SettingsRepository.Snapshot(0,p,true,false);byte[] encoded=SettingsRepository.CODEC.encode(s);SettingsRepository.Snapshot d=SettingsRepository.CODEC.decode(ByteBuffer.wrap(encoded));assertEquals(p,d.searchProvider());assertTrue(d.desiredEnabled("outlook"));assertFalse(d.desiredEnabled("music"));assertThrows(IllegalArgumentException.class,()->d.desiredEnabled("browser"));assertArrayEquals(encoded,SettingsRepository.CODEC.encode(d));}}
 @Test public void settingsEditsAreWholeImmutableSnapshotsNotRunningObservations(){SettingsRepository.Snapshot s=new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false);SettingsRepository.Snapshot changed=s.withEnabled("music",true).withSearch(SearchEngines.Provider.GOOGLE);assertFalse(s.desiredEnabled("music"));assertTrue(changed.desiredEnabled("music"));assertEquals(2,changed.metadataRevision());assertEquals(SearchEngines.Provider.GOOGLE,changed.searchProvider());}
 @Test public void settingsUnknownProviderBooleanTailAndTruncationReject(){byte[] b=SettingsRepository.CODEC.encode(new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false));byte[] bool=b.clone();bool[16+2+"bing".length()]=2;assertThrows(IllegalArgumentException.class,()->SettingsRepository.CODEC.decode(ByteBuffer.wrap(bool)));assertThrows(IllegalArgumentException.class,()->SettingsRepository.CODEC.decode(ByteBuffer.wrap(Arrays.copyOf(b,b.length+1))));byte[] unknown=new NativeRecordCodec.Writer("RBSETT03",200).nonnegative(0).text("unknown",16,false).bool(false).bool(false).text("EXCLUSIVE",16,false).bool(true).text("https://cn.bing.com/",8192,false).finish();assertThrows(IllegalArgumentException.class,()->SettingsRepository.CODEC.decode(ByteBuffer.wrap(unknown)));}
 @Test public void recordFamiliesHaveIndependentMagicAndNoJavaSerialization(){byte[] settings=SettingsRepository.CODEC.encode(new SettingsRepository.Snapshot(0,SearchEngines.Provider.BING,false,false));assertThrows(IllegalArgumentException.class,()->BookmarkStore.CODEC.decode(ByteBuffer.wrap(settings)));assertThrows(IllegalArgumentException.class,()->HistoryStore.CODEC.decode(ByteBuffer.wrap(settings)));}
}
